contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable {
        require(dummy >= 0);

        bool firstReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        bool secondReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(firstReverted == false && secondReverted == false);
    }

    receive() external payable {}
}

