// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy >= 0);
        bool firstReverted;
        try c.Initialized() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        bool secondReverted;
        try c.Initialized() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assertTrue(firstReverted == false && secondReverted == false);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
